import sys
import os
import hashlib
import importlib.util
import logging
import inspect
from types import ModuleType
from typing import Dict, Set, Any, Optional, Callable
from concurrent.futures import ThreadPoolExecutor

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ModularSystem:
    def __init__(self, hash_algorithm: str = 'sha256'):
        self.hash_algorithm = hash_algorithm
        self.modules: Dict[str, ModuleType] = {}

    def _get_hasher(self):
        try:
            return hashlib.new(self.hash_algorithm)
        except ValueError:
            raise ValueError(f"Unsupported hash algorithm: {self.hash_algorithm}")

    def get_file_metadata(self, filepath: str) -> Dict[str, Any]:
        try:
            stat = os.stat(filepath)
            with open(filepath, 'rb') as f:
                content = f.read()

            hasher = self._get_hasher()
            hasher.update(content)

            return {
                "path": filepath,
                "filename": os.path.basename(filepath),
                "size": stat.st_size,
                "modified": stat.st_mtime,
                "created": stat.st_ctime,
                "hash": hasher.hexdigest(),
                "extension": os.path.splitext(filepath)[1],
            }
        except (FileNotFoundError, PermissionError) as e:
            logging.error(f"Error accessing file {filepath}: {e}")
            return {"path": filepath, "error": str(e)}

    def find_file_groups(self, base_path: str, max_depth: int = 2, file_filter: Optional[Callable[[str], bool]] = None) -> Dict[str, Set[str]]:
        groups: Dict[str, Set[str]] = {}
        file_filter = file_filter or (lambda x: x.endswith(('.py',)))
        def process_file(root, file):
            filepath = os.path.join(root, file)
            try:
                with open(filepath, 'rb') as f:
                    content = f.read()
                    hasher = self._get_hasher()
                    hasher.update(content)
                    hash_code = hasher.hexdigest()
                if hash_code not in groups:
                    groups[hash_code] = set()
                groups[hash_code].add(filepath)
            except (PermissionError, IsADirectoryError, OSError) as e:
                logging.warning(f"Could not process file {filepath}: {e}")

        with ThreadPoolExecutor(max_workers=4) as executor:
            for root, _, files in os.walk(base_path):
                depth = root[len(base_path):].count(os.sep)
                if depth > max_depth:
                    continue
                for file in files:
                    if file_filter(file):
                        executor.submit(process_file, root, file)

        return groups

    def inspect_module(self, module_name: str) -> Optional[Dict[str, Any]]:
        try:
            module = importlib.import_module(module_name)
            module_info = {
                "name": getattr(module, '__name__', 'Unknown'),
                "file": getattr(module, '__file__', 'Unknown path'),
                "doc": getattr(module, '__doc__', 'No documentation'),
                "attributes": {},
                "functions": {},
                "classes": {}
            }
            for name, obj in inspect.getmembers(module):
                if name.startswith('_'):
                    continue
                try:
                    if inspect.isfunction(obj):
                        module_info['functions'][name] = {
                            "signature": str(inspect.signature(obj)),
                            "doc": obj.__doc__
                        }
                    elif inspect.isclass(obj):
                        module_info['classes'][name] = {
                            "methods": [m for m in dir(obj) if not m.startswith('_')],
                            "doc": obj.__doc__
                        }
                    else:
                        module_info['attributes'][name] = str(obj)
                except Exception as member_error:
                    logging.warning(f"Error processing member {name}: {member_error}")
            return module_info
        except Exception as e:
            logging.error(f"Error inspecting module {module_name}: {e}")
            return {"error": str(e)}

    def create_module(self, module_name: str, module_code: str, **kwargs) -> Optional[ModuleType]:
        try:
            dynamic_module = ModuleType(module_name)
            dynamic_module.__dict__.update(kwargs)
            exec(module_code, dynamic_module.__dict__)
            sys.modules[module_name] = dynamic_module
            self.modules[module_name] = dynamic_module
            logging.info(f"Dynamic module '{module_name}' created successfully.")
            return dynamic_module
        except Exception as e:
            logging.error(f"Failed to create dynamic module '{module_name}': {e}")
            return None

    def main(self, base_path: str, depth: int = 2):
        logging.info("\n1. Finding File Groups:")
        file_groups = self.find_file_groups(base_path, max_depth=depth)
        duplicate_groups = {hash_code: files for hash_code, files in file_groups.items() if len(files) > 1}
        logging.info(f"Total file groups: {len(file_groups)}")

        if duplicate_groups:
            logging.info("\nDuplicate File Groups:")
            for i, (hash_code, files) in enumerate(duplicate_groups.items(), 1):
                logging.info(f"\nGroup {i} (Hash: {hash_code[:10]}...):")
                for file in files:
                    logging.info(f"  - {file}")
                if i >= 10:
                    logging.info(f"\n... and {len(duplicate_groups) - 10} more duplicate groups")
                    break

        logging.info("\n2. Module Inspection Example:")
        module_name = 'json'
        module_details = self.inspect_module(module_name)
        if module_details and 'error' in module_details:
            logging.error(f"Inspection Error: {module_details['error']}")
        else:
            logging.info(f"Inspected module: {module_details['name']}")
            logging.info(f"Module file: {module_details['file']}")
            logging.info(f"Functions found: {len(module_details.get('functions', {}))}")
            logging.info(f"Classes found: {len(module_details.get('classes', {}))}")

if __name__ == "__main__":
    system = ModularSystem(hash_algorithm='sha256')
    project_root = os.path.abspath('.')
    system.main(base_path=project_root, depth=3)

import sys
import importlib.util
from pathlib import Path
import mimetypes
import hashlib
import datetime
from typing import Dict, Any, Optional
import json
from dataclasses import dataclass, asdict

@dataclass
class FileMetadata:
    path: str
    size: int
    modified: str
    encoding: str
    suffix: str
    mime_type: str
    hash: str
    is_text: bool
    name: str
    stem: str
    created: float
    symlinks: list[Path] = None
    content: Optional[str] = None

class FilesystemMemory:
    def __init__(self, root_dir: Optional[Path] = None):
        self.root_dir = root_dir or Path(__file__).resolve().parent
        self.loaded_modules: Dict[str, Any] = {}
        self.file_metadata: Dict[str, FileMetadata] = {}

    def _generate_file_hash(self, file_path: Path) -> str:
        hasher = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hasher.update(chunk)
        return hasher.hexdigest()

    def _load_text_content(self, path: Path) -> Optional[str]:
        """Load the text content of a file."""
        try:
            return path.read_text(encoding='utf-8')
        except UnicodeDecodeError:
            return None

    def _extract_file_metadata(self, file_path: Path) -> FileMetadata:
        """Extract metadata from a file."""
        stat = file_path.stat()
        mime_type = mimetypes.guess_type(file_path)[0] or 'application/octet-stream'

        return FileMetadata(
            path=str(file_path),
            size=stat.st_size,
            modified=stat.st_mtime,
            encoding='utf-8',  # Assuming UTF-8 for text files
            suffix=file_path.suffix,
            mime_type=mime_type,
            hash=self._generate_file_hash(file_path),
            is_text='text' in mime_type,
            name=file_path.name,
            stem=file_path.stem,
            created=stat.st_ctime,
            symlinks=[p for p in file_path.parent.glob(f'*{file_path.name}*') if p.is_symlink()],
            content=self._load_text_content(file_path) if 'text' in mime_type else None
        )

    def load_module_from_file(self, file_path: Path) -> Optional[Any]:
        if file_path.suffix != '.py':
            return None

        try:
            module_name = f"{file_path.stem}_module"
            spec = importlib.util.spec_from_file_location(module_name, str(file_path))
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            return module
        except Exception as e:
            print(f"Error loading module from {file_path}: {e}")
            return None

    def scan_filesystem(self, ignore_patterns: Optional[list] = None):
        ignore_patterns = ignore_patterns or [
            '.git', '__pycache__', 'venv', '.env', 
            '*.pyc', '*.log', '*.tmp'
        ]

        for file_path in self.root_dir.rglob('*'):
            if file_path.is_file():
                if any(file_path.match(pattern) for pattern in ignore_patterns):
                    continue

                metadata = self._extract_file_metadata(file_path)
                self.file_metadata[str(file_path)] = metadata

                module = self.load_module_from_file(file_path)
                if module:
                    module_name = f"{file_path.stem}_module"
                    self.loaded_modules[module_name] = module

    def export_metadata(self, output_path: Optional[Path] = None) -> Dict[str, Any]:
        metadata_dict = {
            path: asdict(metadata) 
            for path, metadata in self.file_metadata.items()
        }

        if output_path:
            with open(output_path, 'w') as f:
                json.dump(metadata_dict, f, indent=2)

        return metadata_dict

class ContentRegistry:
    def __init__(self, root_dir: Path):
        self.root_dir = root_dir
        self.metadata: Dict[str, FileMetadata] = {}
        self.modules: Dict[str, Any] = {}
        self._init_mimetypes()

    def _init_mimetypes(self):
        mimetypes.add_type('text/markdown', '.md')
        mimetypes.add_type('text/plain', '.txt')
        mimetypes.add_type('application/python', '.py')

    def _compute_hash(self, path: Path) -> str:
        hasher = hashlib.sha256()
        with open(path, 'rb') as f:
            for chunk in iter(lambda: f.read(65536), b''):
                hasher.update(chunk)
        return hasher.hexdigest()

    def register_file(self, path: Path) -> Optional[FileMetadata]:
        if not path.is_file():
            return None

        stat = path.stat()
        mime_type = mimetypes.guess_type(path)[0] or 'application/octet-stream'

        metadata = FileMetadata(
            path=path,
            mime_type=mime_type,
            size=stat.st_size,
            created=stat.st_ctime,
            modified=stat.st_mtime,
            hash=self._compute_hash(path),
            symlinks=[p for p in path.parent.glob(f'*{path.name}*') if p.is_symlink()],
            content=self._load_text_content(path) if 'text' in mime_type else None
        )

        rel_path = path.relative_to(self.root_dir)
        module_name = f"content_{rel_path.stem}"

        spec = importlib.util.spec_from_file_location(module_name, str(path))
        if spec and spec.loader:
            try:
                module = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(module)
                self.modules[module_name] = module
            except Exception:
                pass

        self.metadata[str(rel_path)] = metadata
        return metadata

    def scan_directory(self):
        for path in self.root_dir.rglob('*'):
            if path.is_file():
                self.register_file(path)

    def export_metadata(self, output_path: Path):
        metadata_dict = {
            str(k): {
                'path': str(v.path),
                'mime_type': v.mime_type,
                'size': v.size,
                'created': datetime.fromtimestamp(v.created).isoformat(),
                'modified': datetime.fromtimestamp(v.modified).isoformat(),
                'hash': v.hash,
                'symlinks': [str(s) for s in (v.symlinks or [])],
                'has_content': v.content is not None
            }
            for k, v in self.metadata.items()
        }
        output_path.write_text(json.dumps(metadata_dict, indent=2))

    def create_module(self, metadata: FileMetadata) -> str:
        rel_path = metadata.path.relative_to(self.root_dir)
        module_name = f"content_{rel_path.stem}"

        if metadata.mime_type.startswith('text/'):
            content = metadata.path.read_text(errors='replace')
        else:
            content = f"Binary file: {metadata.mime_type}"

        return f'''
"""File: {rel_path}
Type: {metadata.mime_type}
Size: {metadata.size} bytes
Hash: {metadata.hash}
"""

CONTENT = """{content}"""

def get_metadata():
    return {metadata.__dict__}

@lambda _: _()
def init():
    global __file_loaded__
    __file_loaded__ = True
    return True
'''

def main():
    fs_memory = FilesystemMemory()
    fs_memory.scan_filesystem()
    metadata = fs_memory.export_metadata(
        Path(__file__).parent / 'filesystem_metadata.json'
    )

    print(f"Total files scanned: {len(metadata)}")
    print(f"Modules loaded: {len(fs_memory.loaded_modules)}")
    print("File metadata exported to 'filesystem_metadata.json'")

    for file_path, meta in list(metadata.items())[:5]:
        print(f"\nFile: {file_path}")
        print(json.dumps(meta, indent=2))

if __name__ == "__main__":
    main()
